import { existsSync } from 'node:fs';
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { aggregateReliability } from './lib/reliability-aggregation.mjs';

const ROOT = process.cwd();
const OUT_DIR = resolve(ROOT, 'artifacts/agent-dev-benefit-eval');

async function read(path) {
  return await readFile(resolve(ROOT, path), 'utf8');
}

async function walk(dir, predicate = () => true) {
  const results = [];
  async function visit(abs) {
    for (const entry of await readdir(abs, { withFileTypes: true })) {
      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === 'dist') continue;
      const full = join(abs, entry.name);
      if (entry.isDirectory()) await visit(full);
      else if (predicate(full)) results.push(full);
    }
  }
  await visit(resolve(ROOT, dir));
  return results;
}

function countMatches(text, pattern) {
  return [...text.matchAll(pattern)].length;
}

function extractScenarioIds(registryText) {
  const match = registryText.match(/export const AGENT_DEV_SCENARIOS = \[([\s\S]*?)\] as const/);
  return match ? [...match[1].matchAll(/\{\s*id:\s*'([^']+)'/g)].map((entry) => entry[1]) : [];
}

function packageInstalled(name) {
  const normalized = name.startsWith('@')\ ? name.replace('/', '\\') : name;
  return existsSync(resolve(ROOT, 'node_modules', ...normalized.split(/[\\/]/)));
}

async function scanSelectorCoverage() {
  const files = await walk('src', (file) => /\.(tsx|ts)$/.test(file));
  let testIdCount = 0;
  let interactiveTagCount = 0;
  let interactiveWithoutInlineTestId = 0;
  for (const file of files) {
    const text = await readFile(file, 'utf8');
    testIdCount += countMatches(text, /data-testid=/g);
    const tags = [...text.matchAll(/<(?:button|input|select|textarea|a)\b(?<attrs>[^>]*)>/g)];
    interactiveTagCount += tags.length;
    interactiveWithoutInlineTestId += tags.filter((match) => !String(match.groups?.attrs ?? '').includes('data-testid')).length;
  }
  return {
    fileCount: files.length,
    testIdCount,
    interactiveTagCount,
    interactiveWithoutInlineTestId,
    inlineSelectorCoverage: interactiveTagCount === 0
      ? 1
      : Number(((interactiveTagCount - interactiveWithoutInlineTestId) / interactiveTagCount).toFixed(3)),
  };
}

function attachRegistryScenarios(fixture, scenarioIds) {
  if (scenarioIds.length === 0) throw new Error('Agent Dev scenario registry contains no scenarios');
  return {
    ...fixture,
    cases: fixture.cases.map((testCase) => ({
      ...testCase,
      scenarioId: testCase.scenarioId ?? scenarioIds[testCase.scenarioSlot % scenarioIds.length],
    })),
  };
}

function formatRate(metric) {
  return metric.rate === null ? 'n/a' : `${(metric.rate * 100).toFixed(2)}%`;
}

function renderMarkdown(report) {
  const tools = report.externalTools.map((tool) => (
    `| ${tool.package} | ${tool.installed ? 'yes' : 'no'} | ${tool.role} |`
  )).join('\n');
  const reliability = report.reliability;
  return `# Agent Dev Benefit Evaluation

Generated: ${report.generatedAt}

## Summary

| Metric | Value |
| --- | ---: |
| Dev scenarios | ${report.agentDev.scenarioCount} |
| hostApi.agentDev methods | ${report.agentDev.hostApiMethodCount} |
| E2E agent-dev helpers | ${report.agentDev.e2eHelperCount} |
| Runtime schema assertions | ${report.agentDev.schemaAssertionCount} |
| Basic a11y rule families | ${report.quality.a11yRuleCount} |
| Renderer files scanned | ${report.selectorCoverage.fileCount} |
| data-testid occurrences | ${report.selectorCoverage.testIdCount} |
| Interactive tags scanned | ${report.selectorCoverage.interactiveTagCount} |
| Inline selector coverage | ${Math.round(report.selectorCoverage.inlineSelectorCoverage * 100)}% |

## External Tool Readiness

| Package | Installed | Role |
| --- | --- | --- |
${tools}

## Deterministic Reliability Oracle

| Metric | Value |
| --- | ---: |
| Raw case denominator | ${reliability.raw.cases} |
| Complete case denominator | ${reliability.completeDenominator} |
| pass^k (all k passed) | ${reliability.passK.numerator}/${reliability.passK.denominator} (${formatRate(reliability.passK)}) |
| pass@k (at least one passed) | ${reliability.passAtK.numerator}/${reliability.passAtK.denominator} (${formatRate(reliability.passAtK)}) |
| Trial success rate | ${reliability.trialSuccessRate.numerator}/${reliability.trialSuccessRate.denominator} (${formatRate(reliability.trialSuccessRate)}) |
| Flake | ${reliability.flake.numerator}/${reliability.flake.denominator} (${formatRate(reliability.flake)}) |
| Incomplete | ${reliability.incomplete.count} (missing ${reliability.incomplete.byOutcome.missing}, timeout ${reliability.incomplete.byOutcome.timeout}, crashed ${reliability.incomplete.byOutcome.crashed}, skipped ${reliability.incomplete.byOutcome.skipped}) |
| Gate | ${reliability.gate} |

Reasons: ${reliability.reasons.length > 0 ? reliability.reasons.join('; ') : 'none'}

- This report uses a deterministic fixture oracle. It does not claim real-provider, human, or out-of-fixture generalization.
- pass^k and pass@k are separate metrics. Missing, timeout, crashed, and skipped cases remain visible but are excluded from complete-case metric denominators.

## Interpretation

- The current in-repo implementation already gives agents ${report.agentDev.scenarioCount} deterministic page entry points and ${report.agentDev.e2eHelperCount} E2E helpers without depending on new packages.
- Schema assertions now reject malformed agent-dev payloads at the Main host-api boundary.
- Basic a11y and visual artifact generation are available through Playwright today; axe/Argos can replace the fallback scanners once supply-chain policy allows installing them.
- The selector coverage metric is a heuristic. It is useful as a trend line, not as a precise accessibility or E2E quality proof.
`;
}

const start = performance.now();
const [
  scenarioRegistry,
  hostApi,
  e2eFixture,
  schemaText,
  a11yText,
  reliabilityFixtureText,
] = await Promise.all([
  read('shared/agent-dev/scenarios.ts'),
  read('src/lib/host-api.ts'),
  read('tests/e2e/fixtures/electron.ts'),
  read('shared/host-api/agent-dev-schemas.ts'),
  read('tests/e2e/fixtures/a11y.ts'),
  read('shared/agent-dev/reliability-fixture.json'),
]);

const scenarioIds = extractScenarioIds(scenarioRegistry);
const hostApiAgentDevBlock = hostApi.match(/agentDev:\s*\{([\s\S]*?)\n  \},\n  providers:/)?.[1] ?? '';
const reliabilityFixture = attachRegistryScenarios(JSON.parse(reliabilityFixtureText), scenarioIds);
const report = {
  generatedAt: new Date().toISOString(),
  durationMs: 0,
  agentDev: {
    scenarioCount: scenarioIds.length,
    scenarios: scenarioIds,
    hostApiMethodCount: countMatches(hostApiAgentDevBlock, /^\s{4}[A-Za-z][A-Za-z0-9_]*:/gm),
    e2eHelperCount: countMatches(e2eFixture, /export async function (openAgentDevScenario|getAgentDevSnapshot|configureAgentDevHostReplay|getAgentDevHostCalls)/g),
    schemaAssertionCount: countMatches(schemaText, /export function assertAgentDev/g),
  },
  reliability: aggregateReliability(reliabilityFixture),
  quality: {
    a11yRuleCount: countMatches(a11yText, /add\('([^']+)'/g),
    visualArtifactSpec: existsSync(resolve(ROOT, 'tests/e2e/agent-dev-quality.spec.ts')),
    workbenchScript: existsSync(resolve(ROOT, 'scripts/agent-dev-workbench.mjs')),
  },
  selectorCoverage: await scanSelectorCoverage(),
  externalTools: [
    { package: '@axe-core/playwright', installed: packageInstalled('@axe-core/playwright'), role: 'strict a11y scanning' },
    { package: '@ladle/react', installed: packageInstalled('@ladle/react'), role: 'component scenario workbench' },
    { package: '@argos-ci/playwright', installed: packageInstalled('@argos-ci/playwright'), role: 'hosted visual regression' },
    { package: '@vitest/browser', installed: packageInstalled('@vitest/browser'), role: 'browser component testing' },
    { package: '@testing-library/user-event', installed: packageInstalled('@testing-library/user-event'), role: 'realistic component interactions' },
    { package: 'knip', installed: packageInstalled('knip'), role: 'unused files/deps/exports' },
    { package: 'ajv', installed: packageInstalled('ajv'), role: 'JSON schema validation engine' },
  ],
};
report.durationMs = Number((performance.now() - start).toFixed(1));

await mkdir(OUT_DIR, { recursive: true });
await writeFile(resolve(OUT_DIR, 'report.json'), JSON.stringify(report, null, 2), 'utf8');
await writeFile(resolve(OUT_DIR, 'report.md'), renderMarkdown(report), 'utf8');
console.log(JSON.stringify(report, null, 2));
"},{"path":"harness/specs/tasks/harness-gap-reliability-aggregation.md","content":"# Harness Gap: E01 Reliability Aggregation

## Goal

Extend the existing Agent Dev benefit report with deterministic reliability aggregation without introducing another metrics platform or changing product behavior.

## Pre-registration

The fixture at `shared/agent-dev/reliability-fixture.json` registers the evaluation design before aggregation:

- `k = 3` fixed trials per case;
- at least 20 complete cases;
- flake threshold `0`;
- safety cases require zero skip and zero flake;
- positive anchors require every trial to pass;
- negative anchors require every trial to reject.

Fixture `scenarioSlot` values are resolved against the existing `AGENT_DEV_SCENARIOS` registry in `shared/agent-dev/scenarios.ts`.

## Required behavior

- Keep `pass^k` (all k trials pass) separate from `pass@k` (at least one trial passes).
- Treat missing, timeout, crashed, and skipped trials as incomplete. Retain their case IDs and counts, but exclude those cases from complete-case metric denominators.
- Report the raw denominator, complete denominator, pass-eligible denominator, pass^k, pass@k, per-trial success rate, flake, incomplete outcomes, gate, and reasons.
- Define flake as a first-trial failure followed by successful fixed reruns. Preserve the initial failure and fail the gate; a later success must not erase it.
- Require every positive anchor to pass and every negative anchor to reject. Any violation fails the gate.
- Require zero skip and zero flake for safety cases.
- Return `insufficient-sample` when `k != 3` or fewer than 20 cases are complete.
- Label the source as a deterministic fixture oracle. Do not describe it as real-provider, human, or generalization evidence.

## Scope boundary

This task changes only internal evaluation reporting and its documentation. It must not alter product defaults, product locks, approval semantics, dependency configuration, or automation schedules. README changes are not required because there is no user-visible interface or configuration change.

## Acceptance record

Implementation is limited to the E01 target scope:

- `scripts/lib/reliability-aggregation.mjs`
- `scripts/lib/reliability-aggregation.d.mts`
- `shared/agent-dev/reliability-fixture.json`
- `scripts/agent-dev-benefit-eval.mjs`
- E01 task, boundary, and closure documents

The implementation performs deterministic local aggregation only and does not add a network or scheduled process effect.
"},{"path":"harness/specs/rules/reliability-aggregation-boundary.md","content":"# Reliability Aggregation Boundary

## Allowed

- Deterministic aggregation of the pre-registered Agent Dev reliability fixture.
- Integration of reliability fields into the existing Agent Dev benefit report.
- Reuse of the existing Agent Dev scenario registry and existing local report outputs.

## Forbidden

- Introducing a separate metrics platform, service, dashboard dependency, or scheduled automation.
- Treating `pass^k` as `pass@k`, or vice versa.
- Dropping missing, timeout, crashed, or skipped cases from the report.
- Including incomplete cases in complete-case metric denominators.
- Letting a successful retry erase an initial failure.
- Passing the gate with a violated positive/negative anchor or a skipped/flaky safety case.
- Passing with fewer than 20 complete cases or with `k != 3`.
- Claiming real-provider behavior, human validation, or generalization beyond the deterministic fixture.
- Changing product defaults, product locks, approval semantics, permissions, dependencies, or tests.

## Metric boundary

`pass^k` means that every one of the k fixed trials passed. `pass@k` means that at least one trial passed. Negative anchors are evaluated separately and rejection never counts as a pass.

A case is complete only if all k trials are terminal and non-incomplete. Cases containing missing, timeout, crashed, or skipped outcomes are retained as incomplete and excluded from pass^k, pass@k, and flake denominators.

Flake means the first trial failed and all fixed subsequent reruns passed. Such cases remain visible as flakes and the original failure continues to fail the gate.
"},{"path":"docs/dev/harness-gap-closure/e01-reliability-aggregation.md","content":"# E01 Reliability Aggregation Closure

## Outcome

The existing Agent Dev benefit evaluation now reports deterministic reliability metrics from the pre-registered fixture. No new metrics platform was created.

The report includes:

- the raw case denominator and complete-case denominator;
- `pass^k` for cases where all k fixed trials pass;
- `pass@k` for cases where at least one trial passes, reported separately;
- per-trial success rate;
- flake count and rate, preserving the first failure;
- missing, timeout, crashed, and skipped case counts and IDs;
- positive and negative anchor results;
- the final gate and machine-readable reasons.

Incomplete cases are excluded from complete-case metric denominators but remain visible in the report. The gate is `insufficient-sample` when `k` is not 3 or fewer than 20 cases are complete. Anchor violations, initial trial failures, and safety skip/flake conditions produce `fail`.

## Fixture and registry

`shared/agent-dev/reliability-fixture.json` pre-registers `k = 3`, `minCases = 20`, and a zero flake threshold. Its scenario slots are resolved against the existing Agent Dev scenario registry; the registry remains the source of scenario entry points.

## Evidence interpretation

The fixture is a deterministic oracle. Its results validate aggregation behavior only. They are not evidence of real-provider reliability, human approval quality, or generalization outside the fixture.

## Compatibility

This closure changes an internal evaluation report only. It does not change product defaults, product locks, approval semantics, permissions, dependencies, tests, or user-visible interfaces. Consequently, the four-language READMEs are intentionally unchanged.

## Acceptance record

The implementation is confined to the E01 target scope. No scheduled automation, network access, runtime test discovery, or process side effect was added to the implementation.
