const INCOMPLETE_OUTCOMES = new Set(['missing', 'timeout', 'crashed', 'skipped']);
const ALL_OUTCOMES = new Set([...COMPLETE_OUTCOMES, ...INCOMPLETE_OUTCOMES]);

function ratio(numerator, denominator) {
  return denominator === 0 ? null : Number((numerator / denominator).toFixed(6));
}

function countBy(items, selector) {
  return items.reduce((counts, item) => {
    const key = selector(item);
    counts[key] = (counts[key] ?? 0) + 1;
    return counts;
  }, {});
}

function assertFixture(fixture) {
  if (!fixture || typeof fixture !== 'object' || Array.isArray(fixture)) {
    throw new TypeError('Reliability fixture must be an object');
  }
  if (!Number.isInteger(fixture.k) || fixture.k < 1) {
    throw new TypeError('Reliability fixture k must be a positive integer');
  }
  if (!Number.isInteger(fixture.minCases) || fixture.minCases < 1) {
    throw new TypeError('Reliability fixture minCases must be a positive integer');
  }
  if (!Array.isArray(fixture.cases)) {
    throw new TypeError('Reliability fixture cases must be an array');
  }
  for (const [index, testCase] of fixture.cases.entries()) {
    if (!testCase || typeof testCase.id !== 'string' || testCase.id.length === 0) {
      throw new TypeError(`Reliability case ${index} must have an id`);
    }
    if (!['pass', 'reject'].includes(testCase.expectedOutcome)) {
      throw new TypeError(`Reliability case ${testCase.id} has invalid expectedOutcome`);
    }
    if (!Array.isArray(testCase.trials) || testCase.trials.length !== fixture.k) {
      throw new TypeError(`Reliability case ${testCase.id} must contain exactly k trials`);
    }
    for (const trial of testCase.trials) {
      if (!trial || !ALL_OUTCOMES.has(trial.outcome)) {
        throw new TypeError(`Reliability case ${testCase.id} has an invalid trial outcome`);
      }
    }
  }
}

/**
 * Aggregates a deterministic reliability fixture. A case is complete only when
 * every one of its k trials has a terminal, non-incomplete outcome. Incomplete
 * cases remain visible but do not enter pass^k, pass@k, or flake denominators.
 *
 * pass^k and pass@k are deliberately distinct:
 *   pass^k: every trial passed (at least one passing attempt per trial);
 *   pass@k: at least one trial passed.
 * Rejection is a successful negative-anchor outcome, not a pass.
 */
export function aggregateReliability(fixture) {
  assertFixture(fixture);

  const k = fixture.k;
  const allTrials = fixture.cases.flatMap((testCase) => testCase.trials);
  const completeCases = fixture.cases.filter((testCase) => (
    testCase.trials.every((trial) => COMPLETE_OUTCOMES.has(trial.outcome))
  ));
  const incompleteCases = fixture.cases.filter((testCase) => (
    testCase.trials.some((trial) => INCOMPLETE_OUTCOMES.has(trial.outcome))
  ));
  const passCases = completeCases.filter((testCase) => testCase.expectedOutcome === 'pass');
  const negativeCases = completeCases.filter((testCase) => testCase.expectedOutcome === 'reject');

  const passKCases = passCases.filter((testCase) => testCase.trials.every((trial) => trial.outcome === 'passed'));
  const passKCases = passCases.filter((testCase) => testCase.trials.some((trial) => trial.outcome === 'passed'));
  const flakyCases = passCases.filter((testCase) => (
    testCase.trials[0]?.outcome === 'failed'
    && testCase.trials.slice(1).every((trial) => trial.outcome === 'passed')
  ));
  const initiallyFailedCases = passCases.filter((testCase) => testCase.trials[0]?.outcome !== 'passed');

  const incompleteCaseCounts = countBy(incompleteCases, (testCase) => {
    const incomplete = testCase.trials.find((trial) => INCOMPLETE_OUTCOMES.has(trial.outcome));
    return incomplete?.outcome ?? 'missing';
  });
  const trialOutcomeCounts = countBy(allTrials, (trial) => trial.outcome);
  const completedTrials = allTrials.filter((trial) => COMPLETE_OUTCOMES.has(trial.outcome));

  const positiveAnchors = fixture.cases
    .filter((testCase) => testCase.expectedOutcome === 'pass' && testCase.anchor === 'positive')
    .map((testCase) => ({
      id: testCase.id,
      scenarioId: testCase.scenarioId ?? null,
      satisfied: testCase.trials.length === k
        && testCase.trials.every((trial) => trial.outcome === 'passed'),
    }));
  const negativeAnchors = fixture.cases
    .filter((testCase) => testCase.expectedOutcome === 'reject' && testCase.anchor === 'negative')
    .map((testCase) => ({
      id: testCase.id,
      scenarioId: testCase.scenarioId ?? null,
      satisfied: testCase.trials.length === k
        && testCase.trials.every((trial) => trial.outcome === 'rejected'),
    }));
  const violatedPositiveAnchors = positiveAnchors.filter((anchor) => !anchor.satisfied);
  const violatedNegativeAnchors = negativeAnchors.filter((anchor) => !anchor.satisfied);

  const safetyCaseIds = new Set(fixture.safetyCaseIds ?? []);
  const safetyCases = fixture.cases.filter((testCase) => safetyCaseIds.has(testCase.id));
  const safetySkippedCases = safetyCases.filter((testCase) => (
    testCase.trials.some((trial) => trial.outcome === 'skipped')
  ));
  const safetyFlakyCases = safetyCases.filter((testCase) => (
    testCase.trials[0]?.outcome === 'failed'
    && testCase.trials.slice(1).every((trial) => trial.outcome === 'passed')
  ));

  const reasons = [];
  if (k !== 3) reasons.push(`configured-k-not-3:${k}`);
  if (completeCases.length < fixture.minCases) {
    reasons.push(`complete-cases-below-${fixture.minCases}:${completeCases.length}`);
  }
  if (violatedPositiveAnchors.length > 0) {
    reasons.push(`positive-anchor-violations:${violatedPositiveAnchors.map((anchor) => anchor.id).join(',')}`);
  }
  if (violatedNegativeAnchors.length > 0) {
    reasons.push(`negative-anchor-violations:${violatedNegativeAnchors.map((anchor) => anchor.id).join(',')}`);
  }
  if (safetySkippedCases.length > 0) {
    reasons.push(`safety-skip:${safetySkippedCases.map((testCase) => testCase.id).join(',')}`);
  }
  if (safetyFlakyCases.length > 0) {
    reasons.push(`safety-flake:${safetyFlakyCases.map((testCase) => testCase.id).join(',')}`);
  }
  if (initiallyFailedCases.length > 0) {
    reasons.push(`initial-trial-failure:${initiallyFailedCases.map((testCase) => testCase.id).join(',')}`);
  }

  let gate = 'pass';
  if (reasons.some((reason) => reason.startsWith('configured-k-not-3') || reason.startsWith('complete-cases-below-'))) {
    gate = 'insufficient-sample';
  } else if (reasons.length > 0) {
    gate = 'fail';
  }

  const rawPassDenominator = fixture.cases.filter((testCase) => testCase.expectedOutcome === 'pass').length;
  return {
    oracle: 'deterministic-fixture',
    disclaimer: 'Deterministic fixture oracle only; not evidence of real-provider, human, or out-of-fixture generalization.',
    k,
    minCases: fixture.minCases,
    flakeThreshold: fixture.flakeThreshold,
    raw: {
      cases: fixture.cases.length,
      passCases: rawPassDenominator,
      completeCases: completeCases.length,
      incompleteCases: incompleteCases.length,
      trials: allTrials.length,
      completedTrials: completedTrials.length,
    },
    completeDenominator: completeCases.length,
    passEligibleDenominator: passCases.length,
    passK: {
      definition: 'complete pass-expected cases where all k trials passed',
      numerator: passKCases.length,
      denominator: passCases.length,
      rate: ratio(passKCases.length, passCases.length),
    },
    passKStar: {
      definition: 'complete pass-expected cases where all k trials passed',
      numerator: passKCases.length,
      denominator: passCases.length,
      rate: ratio(passKCases.length, passCases.length),
    },
    passAtK: {
      definition: 'complete pass-expected cases with at least one passing trial',
      numerator: passKCases.length,
      denominator: passCases.length,
      rate: ratio(passKCases.length, passCases.length),
    },
    trialSuccessRate: {
      definition: 'passed trials divided by all non-incomplete trials; rejection is not a pass',
      numerator: trialOutcomeCounts.passed ?? 0,
      denominator: completedTrials.length,
      rate: ratio(trialOutcomeCounts.passed ?? 0, completedTrials.length),
    },
    flake: {
      definition: 'first trial failed and every fixed subsequent rerun passed',
      numerator: flakyCases.length,
      denominator: passCases.length,
      rate: ratio(flakyCases.length, passCases.length),
      caseIds: flakyCases.map((testCase) => testCase.id),
      threshold: fixture.flakeThreshold,
    },
    incomplete: {
      definition: 'cases containing missing, timeout, crashed, or skipped trials; retained but excluded from metric denominators',
      count: incompleteCases.length,
      caseIds: incompleteCases.map((testCase) => testCase.id),
      byOutcome: {
        missing: incompleteCaseCounts.missing ?? 0,
        timeout: incompleteCaseCounts.timeout ?? 0,
        crashed: incompleteCaseCounts.crashed ?? 0,
        skipped: incompleteCaseCounts.skipped ?? 0,
      },
    },
    trialOutcomes: {
      passed: trialOutcomeCounts.passed ?? 0,
      failed: trialOutcomeCounts.failed ?? 0,
      rejected: trialOutcomeCounts.rejected ?? 0,
      missing: trialOutcomeCounts.missing ?? 0,
      timeout: trialOutcomeCounts.timeout ?? 0,
      crashed: trialOutcomeCounts.crashed ?? 0,
      skipped: trialOutcomeCounts.skipped ?? 0,
    },
    anchors: {
      positive: positiveAnchors,
      negative: negativeAnchors,
      violatedPositive: violatedPositiveAnchors,
      violatedNegative: violatedNegativeAnchors,
    },
    safety: {
      caseIds: [...safetyCaseIds],
      skippedCaseIds: safetySkippedCases.map((testCase) => testCase.id),
      flakyCaseIds: safetyFlakyCases.map((testCase) => testCase.id),
    },
    gate,
    reasons,
  };
}

export default aggregateReliability;
"},{"path":"scripts/lib/reliability-aggregation.d.mts","content":"export type ReliabilityTrialOutcome =
  | 'passed'
  | 'failed'
  | 'rejected'
  | 'missing'
  | 'timeout'
  | 'crashed'
  | 'skipped';

export interface ReliabilityTrial {
  outcome: ReliabilityTrialOutcome;
}

export interface ReliabilityCase {
  id: string;
  scenarioId?: string | null;
  scenarioSlot?: number;
  expectedOutcome: 'pass' | 'reject';
  anchor?: 'positive' | 'negative';
  trials: ReliabilityTrial[];
}

export interface ReliabilityFixture {
  k: number;
  minCases: number;
  flakeThreshold: number;
  safetyCaseIds?: string[];
  cases: ReliabilityCase[];
}

export interface ReliabilityMetric {
  definition: string;
  numerator: number;
  denominator: number;
  rate: number | null;
}

export interface ReliabilityAggregation {
  oracle: 'deterministic-fixture';
  disclaimer: string;
  k: number;
  minCases: number;
  flakeThreshold: number;
  raw: {
    cases: number;
    passCases: number;
    completeCases: number;
    incompleteCases: number;
    trials: number;
    completedTrials: number;
  };
  completeDenominator: number;
  passEligibleDenominator: number;
  passK: ReliabilityMetric;
  passKStar: ReliabilityMetric;
  passAtK: ReliabilityMetric;
  trialSuccessRate: ReliabilityMetric;
  flake: ReliabilityMetric & { caseIds: string[]; threshold: number };
  incomplete: {
    definition: string;
    count: number;
    caseIds: string[];
    byOutcome: Record<'missing' | 'timeout' | 'crashed' | 'skipped', number>;
  };
  trialOutcomes: Record<ReliabilityTrialOutcome, number>;
  anchors: {
    positive: Array<{ id: string; scenarioId: string | null; satisfied: boolean }>;
    negative: Array<{ id: string; scenarioId: string | null; satisfied: boolean }>;
    violatedPositive: Array<{ id: string; scenarioId: string | null; satisfied: boolean }>;
    violatedNegative: Array<{ id: string; scenarioId: string | null; satisfied: boolean }>;
  };
  safety: {
    caseIds: string[];
    skippedCaseIds: string[];
    flakyCaseIds: string[];
  };
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
}

export function aggregateReliability(fixture: ReliabilityFixture): ReliabilityAggregation;

export default aggregateReliability;
